        public void commitOffset(
            long producerId,
            String groupId,
            String topic,
            int partition,
            long offset,
            int leaderEpoch,
            long commitTimestamp
        ) {
            replay(producerId, CoordinatorRecordHelpers.newOffsetCommitRecord(
